// One picture per variant: id, the entry it belongs to, what it is painted from, and the words it is matched on.
function picturesOf(entry){
 return entry.variants.map((v,i)=>({id:entry.id+'-'+(i+1),entry:entry.id,kind:entry.id.split('-')[0],family:entry.family,size:entry.size,band:entry.band,terrains:entry.terrains,names:entry.names,tags:[...new Set([...entry.tags,...v.tags])],variantTags:v.tags,templates:entry.templates,...(v.template?{template:v.template}:{}),name:displayName(entry,i),look:v.template?templateLooks[v.template]:entry.look,twist:v.twist,description:(entry.look+(v.twist?' '+v.twist:'')).trim()}));
}
function displayName(entry,i){const base=entry.names[0];return (base.charAt(0).toUpperCase()+base.slice(1))+(entry.variants.length>1?' ('+(i+1)+')':'');}
const pictures=entries.flatMap(picturesOf);
module.exports={entries,pictures,picturesOf,families,sizes,terrains:all,templateLooks};
